{
  "core_question": "How should a US-based clinical-stage biotech structure and value a co-development/co-commercialization deal with an EU pharma for a single Phase 3 oncology asset, considering clinical risk, regulatory/IP exposure, and financial economics?",
  "rationale": "The question spans clinical program assessment (healthcare), jurisdictional IP and regulatory structuring (legal), and valuation/milestone economics (finance).",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "What are the primary clinical program risks for a single Phase 3 oncology asset in a US-based biotech seeking accelerated approval, and how should these risks be quantified to inform valuation?",
    "legal": "How should the territorial rights split (US to the biotech, EU/UK to the pharma) be structured legally to protect IP exposure across jurisdictions, including considerations of FDA accelerated approval, EMA regulations, and post-Brexit UK rules?",
    "finance": "What is a recommended approach for calculating rNPV and milestone calibration in this co-development deal, taking into account upfront payments, tiered royalties, territorial rights split, and the asset's Phase 3 status with potential accelerated approval?"
  },
  "requires_recency_disclosure": true,
  "recency_notes": "Potentially stale FDA accelerated approval guidance, EMA regulatory updates, post-Brexit UK IP and regulatory changes."
}
